-- 集中管理 isInAutoControl 的加减:
Maze2DStates.AddIsInAutoControl = function()
    Maze2DStates.isInAutoControl = Maze2DStates.isInAutoControl + 1
    --print( "加 isInAutoControl = " .. Maze2DStates.isInAutoControl )
end

Maze2DStates.MinusIsInAutoControl = function()
    Maze2DStates.isInAutoControl = Maze2DStates.isInAutoControl - 1
    --print( "减 isInAutoControl = " .. Maze2DStates.isInAutoControl )
end


-- 判断 玩家是否有权限控制 迷宫:
Maze2DStates.IsInAutoControlLegal = function()
    
    -- !!! 可能存在的 异常:
    if Maze2DStates.isInAutoControl < 0 then 
        printError( "异常 isInAutoControl: (a)" .. tostring(Maze2DStates.isInAutoControl) )
        Maze2DStates.isInAutoControl = 0
    end

    return (Maze2DStates.isInAutoControl == 0)
end




-- 在单次 2D迷宫 过程中, MazeMainUI 实例会被先生成, 然后再生成具体的 puzzle 实例, 
-- 且在 puzzle 实例生命周期后, 随着战斗的进入退出, MazeMainUI 实例会被反复 卸载和新建 
-- 所以本函数要在 MazeMainUI 实例 和 puzzle 实例内 都被调用, 以确保一定绑定成功了
Maze2DStates.BindAllBtnFuncs = function()

    local BindBtnFunc = function( btnName_ )
        if not isNull( Maze2DStates.WhenPushBtns[btnName_] ) then 
            SetButtonAction(Maze2DStates.Btns[btnName_].gameObject, Maze2DStates.WhenPushBtns[btnName_])
        end
    end

    BindBtnFunc( "Back" )
    BindBtnFunc( "Dismantle" )
    BindBtnFunc( "Reset" )
    BindBtnFunc( "Choose" )

    BindBtnFunc( "Up" )
    BindBtnFunc( "Down" )
    BindBtnFunc( "Right" )
    BindBtnFunc( "Left" )

    BindBtnFunc( "Up2" )
    BindBtnFunc( "Down2" )
    BindBtnFunc( "Right2" )
    BindBtnFunc( "Left2" )

    BindBtnFunc( "Rotate1" )
    BindBtnFunc( "Rotate2" )
end





