-- debug 用:
Maze2DStates.Print = function()
    local ss = "Maze2DStates:"

    function Show(v)
        return isNull(v) and "nil" or tostring(v)
    end

    ss = ss .. "\n mapId = " .. Show(Maze2DStates.mapId)
    ss = ss .. "\n groupId = " .. Show(Maze2DStates.groupId)
    ss = ss .. "\n isFindNewMap = " .. Show(Maze2DStates.isFindNewMap)
    ss = ss .. "\n mapDecryptionHomeDatas = " .. Show(Maze2DStates.mapDecryptionHomeDatas)
    ss = ss .. "\n isBattleWin = " .. Show(Maze2DStates.isBattleWin)
    ss = ss .. "\n isMazeMainUIOpen = " .. Show(Maze2DStates.isMazeMainUIOpen)
    ss = ss .. "\n isInAutoControl = " .. Show(Maze2DStates.isInAutoControl)
    ---
    print( ss )
end


